'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useId, useState } from 'react';

import {
  SettingsIcon,
  TriangleAlertIcon,
  UsersIcon,
} from '@/registry/ndeko/lib/icons';

import { DangerZone } from './danger-zone';
import {
  FIELD_SECTION,
  INITIAL_WORKSPACE,
  INVITE_POLICIES,
  ROLE_OPTIONS,
  SECTION_KEYS,
  TIME_ZONES,
  WORKSPACE_HOST,
  type Role,
  type SectionId,
  type WorkspaceField,
  type WorkspaceValues,
} from './data';
import { RoleChoice } from './role-choice';
import {
  SETTINGS_SURFACE_BASE,
  SectionPanel,
  SectionTabs,
  SelectRow,
  SettingsPage,
  SettingsRow,
  SettingsSection,
  SwitchRow,
  TextRow,
  UnsavedBar,
  hasChangeIn,
  useSettingsDraft,
  type NavItem,
} from './settings-kit';

type WorkspaceErrors = Partial<Record<WorkspaceField, string>>;

const SECTIONS = [
  { id: 'general', label: 'General', icon: SettingsIcon },
  { id: 'members', label: 'Members', icon: UsersIcon },
  { id: 'danger', label: 'Danger zone', icon: TriangleAlertIcon },
] as const;

const FIELD_ORDER: WorkspaceField[] = ['name', 'slug', 'allowedDomain'];

const SLUG_PATTERN = /^[a-z0-9]+(-[a-z0-9]+)*$/;

const DOMAIN_PATTERN = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function errorsOf(values: WorkspaceValues): WorkspaceErrors {
  const errors: WorkspaceErrors = {};
  const name = values.name.trim();
  const domain = values.allowedDomain.trim();
  const hasDomain = domain.length > 0;
  const isSlugValid = SLUG_PATTERN.test(values.slug);
  const isDomainValid = DOMAIN_PATTERN.test(domain);
  const isDomainMalformed = hasDomain && !isDomainValid;
  if (name.length === 0) {
    errors.name = 'Give the workspace a name';
  }
  if (!isSlugValid) {
    errors.slug = 'Use lowercase letters and digits, joined by single hyphens';
  }
  if (isDomainMalformed) {
    errors.allowedDomain =
      'Enter a domain like tidewell.example, without the @';
  }
  return errors;
}

function firstErrorFieldOf(errors: WorkspaceErrors) {
  const field = FIELD_ORDER.find((candidate) => Boolean(errors[candidate]));
  if (field) {
    return field;
  }
  return null;
}

function withoutError(errors: WorkspaceErrors, field: WorkspaceField) {
  if (!errors[field]) {
    return errors;
  }
  const next = { ...errors };
  delete next[field];
  return next;
}

function fixMessageOf(errors: WorkspaceErrors) {
  const messages = Object.values(errors);
  const count = messages.filter(Boolean).length;
  if (count === 0) {
    return undefined;
  }
  if (count === 1) {
    return 'Fix 1 field to save';
  }
  return `Fix ${count} fields to save`;
}

function initialOf(name: string) {
  const trimmed = name.trim();
  if (trimmed.length === 0) {
    return '?';
  }
  const [firstCharacter] = Array.from(trimmed);
  return firstCharacter.toUpperCase();
}

function slugLineOf(slug: string) {
  const address = `${WORKSPACE_HOST}${slug}`;
  return `${address}, old links redirect for 30 days`;
}

function domainLineOf(domain: string) {
  const trimmed = domain.trim();
  if (trimmed.length === 0) {
    return 'Empty: people join only with an invitation';
  }
  return `Anyone with an @${trimmed} address can join`;
}

function fieldIdOf(field: WorkspaceField) {
  return `workspace-${field}`;
}

function focusField(field: WorkspaceField) {
  const fieldId = fieldIdOf(field);
  window.requestAnimationFrame(() => {
    document.getElementById(fieldId)?.focus();
  });
}

/** The workspace has no logo, so its tile carries the initial; the letter swaps as the name changes. */
function WorkspaceTile({ name }: { name: string }) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const initial = initialOf(name);
  const tileStyle = { '--gem': 'var(--primary)' } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={tileStyle}
      className='gem-plate flex size-10 shrink-0 items-center justify-center rounded-lg text-base font-semibold'
    >
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={initial}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {initial}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export default function Settings03() {
  const settings = useSettingsDraft<WorkspaceValues>(INITIAL_WORKSPACE);
  const [section, setSection] = useState<SectionId>('general');
  const [hasSwitched, setHasSwitched] = useState(false);
  const [shownErrors, setShownErrors] = useState<WorkspaceErrors>({});
  const roleHeadingId = useId();
  const draft = settings.draft;
  const savedName = settings.savedValues.name;
  const fixMessage = fixMessageOf(shownErrors);
  const slugLine = slugLineOf(draft.slug);
  const domainLine = domainLineOf(draft.allowedDomain);
  const navItems: NavItem<SectionId>[] = SECTIONS.map((item) => ({
    id: item.id,
    label: item.label,
    icon: item.icon,
    hasChanges: hasChangeIn(settings.changedKeys, SECTION_KEYS[item.id]),
  }));

  function openSection(nextSection: SectionId) {
    setSection(nextSection);
    setHasSwitched(true);
  }

  function changeField<Field extends WorkspaceField>(
    field: Field,
    value: WorkspaceValues[Field]
  ) {
    settings.change(field, value);
    setShownErrors((previous) => withoutError(previous, field));
  }

  function save() {
    const errors = errorsOf(draft);
    const firstField = firstErrorFieldOf(errors);
    setShownErrors(errors);
    if (!firstField) {
      settings.save();
      return;
    }
    const fieldSection = FIELD_SECTION[firstField];
    if (fieldSection !== section) {
      openSection(fieldSection);
    }
    focusField(firstField);
  }

  function discard() {
    settings.discard();
    setShownErrors({});
  }

  function changeName(name: string) {
    changeField('name', name);
  }

  function changeSlug(slug: string) {
    const lowered = slug.toLowerCase();
    changeField('slug', lowered);
  }

  function changeTimeZone(timeZone: string) {
    changeField('timeZone', timeZone);
  }

  function changeRole(role: Role) {
    changeField('defaultRole', role);
  }

  function changeInvitePolicy(policy: string) {
    const option = INVITE_POLICIES.find(
      (candidate) => candidate.value === policy
    );
    if (option) {
      changeField('invitePolicy', option.value);
    }
  }

  function changeApproveJoins(checked: boolean) {
    changeField('approveJoins', checked);
  }

  function changeDomain(domain: string) {
    const lowered = domain.toLowerCase();
    changeField('allowedDomain', lowered);
  }

  const bar = (
    <UnsavedBar
      isShown={settings.isBarShown}
      status={settings.status}
      changeCount={settings.changedKeys.length}
      message={fixMessage}
      onDiscard={discard}
      onSave={save}
    />
  );

  return (
    <SettingsPage
      title='Workspace'
      line='The name, the address and who can join Tidewell Studio. Changes here apply to all 14 members.'
      bar={bar}
    >
      <SectionTabs
        label='Workspace sections'
        items={navItems}
        value={section}
        onValueChange={openSection}
      >
        <SectionPanel value='general' animatesIn={hasSwitched}>
          <SettingsSection
            title='General'
            line='How the workspace shows in the sidebar, links and emails'
          >
            <SettingsRow
              label='Workspace tile'
              line='No logo yet, so the tile shows the first letter of the name'
            >
              <WorkspaceTile name={draft.name} />
            </SettingsRow>
            <TextRow
              inputId={fieldIdOf('name')}
              label='Name'
              line='Shown in the sidebar and in invitations'
              value={draft.name}
              error={shownErrors.name}
              autoComplete='organization'
              maxLength={48}
              onValueChange={changeName}
            />
            <TextRow
              inputId={fieldIdOf('slug')}
              label='Address'
              line={slugLine}
              value={draft.slug}
              error={shownErrors.slug}
              autoComplete='off'
              maxLength={40}
              onValueChange={changeSlug}
            />
            <SelectRow
              label='Time zone'
              line='Days in reports and timesheets close at midnight here'
              value={draft.timeZone}
              options={TIME_ZONES}
              onValueChange={changeTimeZone}
            />
          </SettingsSection>
        </SectionPanel>
        <SectionPanel value='members' animatesIn={hasSwitched}>
          <section
            aria-labelledby={roleHeadingId}
            className='flex flex-col gap-3'
          >
            <div className='flex flex-col gap-0.5'>
              <h2 id={roleHeadingId} className='text-sm font-medium'>
                Default role for new members
              </h2>
              <p className='text-muted-foreground text-xs'>
                Given to everyone who joins from now on; people already in keep
                their role
              </p>
            </div>
            <div className={SETTINGS_SURFACE_BASE}>
              <RoleChoice
                labelledBy={roleHeadingId}
                options={ROLE_OPTIONS}
                value={draft.defaultRole}
                onValueChange={changeRole}
              />
            </div>
          </section>
          <SettingsSection
            title='Joining'
            line='Invitations and the people who can send them'
          >
            <SelectRow
              label='Who can invite'
              line='Invitations last 7 days'
              value={draft.invitePolicy}
              options={INVITE_POLICIES}
              onValueChange={changeInvitePolicy}
            />
            <SwitchRow
              label='Approve new members'
              line='People who join with a link wait until an admin lets them in'
              checked={draft.approveJoins}
              onCheckedChange={changeApproveJoins}
            />
            <TextRow
              inputId={fieldIdOf('allowedDomain')}
              label='Allowed email domain'
              line={domainLine}
              placeholder='company.com'
              value={draft.allowedDomain}
              error={shownErrors.allowedDomain}
              autoComplete='off'
              maxLength={64}
              onValueChange={changeDomain}
            />
          </SettingsSection>
        </SectionPanel>
        <SectionPanel value='danger' animatesIn={hasSwitched}>
          <SettingsSection
            title='Danger zone'
            line='These apply at once and do not wait for Save'
          >
            <DangerZone workspaceName={savedName} />
          </SettingsSection>
        </SectionPanel>
      </SectionTabs>
    </SettingsPage>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useId, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/registry/ndeko/ui/alert-dialog';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import { WORKSPACE_FACTS } from './data';
import { SettingsRow } from './settings-kit';

const HOLD_MS = 2000;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LINE_VARIANTS: Variants = {
  enter: { opacity: 0, y: 4 },
  visible: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -4 },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const COUNT_FORMAT = new Intl.NumberFormat('en');

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function lineVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return LINE_VARIANTS;
}

function clearTimer(timerRef: React.RefObject<number | null>) {
  if (timerRef.current === null) {
    return;
  }
  window.clearTimeout(timerRef.current);
  timerRef.current = null;
}

function isHoldKey(event: React.KeyboardEvent) {
  const isSpace = event.key === ' ';
  const isEnter = event.key === 'Enter';
  return isSpace || isEnter;
}

/**
 * Clip-path moves the fill; with reduced motion the fill fades in over the same two seconds,
 * because the theme drops clip-path transitions in that mode.
 */
function holdFillClassOf(
  isHolding: boolean,
  shouldReduceMotion: boolean | null
) {
  if (shouldReduceMotion) {
    return cn(
      'opacity-0 transition-opacity duration-200',
      isHolding && 'opacity-100 duration-[2000ms] ease-linear'
    );
  }
  return cn(
    '[clip-path:inset(0_100%_0_0)] transition-[clip-path] duration-200 ease-(--ease-out-strong)',
    isHolding && '[clip-path:inset(0_0_0_0)] duration-[2000ms] ease-linear'
  );
}

function holdLabelOf(isHolding: boolean, label: string) {
  if (isHolding) {
    return 'Keep holding';
  }
  return label;
}

type HoldButtonProps = {
  label: string;
  hint: string;
  onComplete: () => void;
};

/** A destructive action that asks for intent: the fill crosses the pill while it is pressed and drains on release. */
function HoldButton({ label, hint, onComplete }: HoldButtonProps) {
  const [isHolding, setIsHolding] = useState(false);
  const timerRef = useRef<number | null>(null);
  const hintId = useId();
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const fillClass = holdFillClassOf(isHolding, shouldReduceMotion);
  const shownLabel = holdLabelOf(isHolding, label);

  useEffect(() => {
    return () => clearTimer(timerRef);
  }, []);

  function startHold() {
    if (timerRef.current !== null) {
      return;
    }
    setIsHolding(true);
    timerRef.current = window.setTimeout(() => {
      timerRef.current = null;
      setIsHolding(false);
      onComplete();
    }, HOLD_MS);
  }

  function stopHold() {
    clearTimer(timerRef);
    setIsHolding(false);
  }

  function pressKey(event: React.KeyboardEvent<HTMLButtonElement>) {
    const isHold = isHoldKey(event);
    if (!isHold) {
      return;
    }
    event.preventDefault();
    if (!event.repeat) {
      startHold();
    }
  }

  function releaseKey(event: React.KeyboardEvent<HTMLButtonElement>) {
    if (isHoldKey(event)) {
      stopHold();
    }
  }

  return (
    <>
      <Button
        variant='outline'
        aria-describedby={hintId}
        onPointerDown={startHold}
        onPointerUp={stopHold}
        onPointerLeave={stopHold}
        onPointerCancel={stopHold}
        onKeyDown={pressKey}
        onKeyUp={releaseKey}
        onBlur={stopHold}
        className='text-destructive-ink touch-none overflow-hidden select-none [-webkit-touch-callout:none]'
      >
        <span
          aria-hidden='true'
          className={cn('bg-destructive/15 absolute inset-0', fillClass)}
        />
        <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.span
              key={shownLabel}
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
            >
              {shownLabel}
            </motion.span>
          </AnimatePresence>
        </AnimatedSize>
      </Button>
      <span id={hintId} className='sr-only'>
        {hint}
      </span>
    </>
  );
}

function SwappingLine({ text }: { text: string }) {
  const shouldReduceMotion = useReducedMotion();
  const variants = lineVariantsOf(shouldReduceMotion);

  return (
    <span className='relative block'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={text}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='block'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

type SwapSlotProps = {
  slotKey: string;
  children: React.ReactNode;
};

function SwapSlot({ slotKey, children }: SwapSlotProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize axis='width' contentClassName='relative flex justify-end'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={slotKey}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

function countOf(count: number, singular: string, plural: string) {
  const digits = COUNT_FORMAT.format(count);
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${digits} ${plural}`;
}

const MEMBERS_LABEL = countOf(WORKSPACE_FACTS.members, 'member', 'members');

const PROJECTS_LABEL = countOf(WORKSPACE_FACTS.projects, 'project', 'projects');

const TASKS_LABEL = countOf(WORKSPACE_FACTS.tasks, 'task', 'tasks');

const GRACE_LABEL = countOf(WORKSPACE_FACTS.graceDays, 'day', 'days');

function accessLineOf(members: number) {
  if (members === 1) {
    return '1 member loses access';
  }
  return `${MEMBERS_LABEL} lose access`;
}

const ACCESS_LINE = accessLineOf(WORKSPACE_FACTS.members);

function archiveLineOf(isArchived: boolean) {
  if (isArchived) {
    return 'Archived just now. Everyone can read, nobody can edit or track time';
  }
  return 'Everyone keeps read access; nobody can edit or track time until you restore it';
}

function deleteLineOf(isScheduled: boolean) {
  if (isScheduled) {
    return `Deletion scheduled for ${WORKSPACE_FACTS.deletionDate}. Until then you can cancel it`;
  }
  return `After ${GRACE_LABEL}, removes ${MEMBERS_LABEL}, ${PROJECTS_LABEL} and ${TASKS_LABEL}`;
}

type DangerZoneProps = {
  workspaceName: string;
};

/** Destructive rows apply at once: archive asks for a two-second hold, delete asks for the name. */
export function DangerZone({ workspaceName }: DangerZoneProps) {
  const [isArchived, setIsArchived] = useState(false);
  const [isDeletionScheduled, setIsDeletionScheduled] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [typedName, setTypedName] = useState('');
  const confirmFieldId = useId();
  const isNameTyped = typedName.trim() === workspaceName;
  const archiveLine = archiveLineOf(isArchived);
  const deleteLine = deleteLineOf(isDeletionScheduled);
  const archiveSlotKey = String(isArchived);
  const deleteSlotKey = String(isDeletionScheduled);

  function archive() {
    setIsArchived(true);
  }

  function restore() {
    setIsArchived(false);
  }

  function openDeletion() {
    setTypedName('');
    setIsDialogOpen(true);
  }

  function changeTypedName(event: React.ChangeEvent<HTMLInputElement>) {
    setTypedName(event.target.value);
  }

  function scheduleDeletion() {
    setIsDeletionScheduled(true);
  }

  function cancelDeletion() {
    setIsDeletionScheduled(false);
  }

  return (
    <>
      <SettingsRow
        label='Archive workspace'
        line={<SwappingLine text={archiveLine} />}
      >
        <SwapSlot slotKey={archiveSlotKey}>
          {isArchived && (
            <Button variant='outline' onClick={restore}>
              Restore workspace
            </Button>
          )}
          {!isArchived && (
            <HoldButton
              label='Hold to archive'
              hint='Press and hold for two seconds to archive the workspace'
              onComplete={archive}
            />
          )}
        </SwapSlot>
      </SettingsRow>
      <SettingsRow
        label='Delete workspace'
        line={<SwappingLine text={deleteLine} />}
      >
        <SwapSlot slotKey={deleteSlotKey}>
          {isDeletionScheduled && (
            <Button variant='outline' onClick={cancelDeletion}>
              Cancel deletion
            </Button>
          )}
          {!isDeletionScheduled && (
            <Button
              variant='outline'
              onClick={openDeletion}
              className='text-destructive-ink'
            >
              Delete workspace
            </Button>
          )}
        </SwapSlot>
      </SettingsRow>
      <AlertDialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{`Delete ${workspaceName}?`}</AlertDialogTitle>
            <AlertDialogDescription>
              {`Nothing is removed for ${GRACE_LABEL}. After that it cannot be undone.`}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <ul className='bg-foreground/[0.03] hairline-divide-y divide-border flex flex-col rounded-lg text-[13px]'>
            <li className='px-3 py-2'>{ACCESS_LINE}</li>
            <li className='px-3 py-2'>{`${PROJECTS_LABEL} and ${TASKS_LABEL} are deleted`}</li>
            <li className='px-3 py-2'>
              Timesheets stay downloadable until the end
            </li>
          </ul>
          <div className='flex flex-col gap-1.5'>
            <label
              htmlFor={confirmFieldId}
              className='text-muted-foreground text-xs'
            >
              Type{' '}
              <span className='text-foreground font-medium'>
                {workspaceName}
              </span>{' '}
              to confirm
            </label>
            <Input
              id={confirmFieldId}
              value={typedName}
              autoComplete='off'
              spellCheck={false}
              onChange={changeTypedName}
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep workspace</AlertDialogCancel>
            <AlertDialogAction
              variant='destructive'
              disabled={!isNameTyped}
              onClick={scheduleDeletion}
            >
              Delete workspace
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

'use client';

import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';

import type { Role, RoleOption } from './data';

function holdersLineOf(holders: number) {
  if (holders === 1) {
    return '1 person has this role today';
  }
  return `${holders} people have this role today`;
}

type RoleChoiceProps = {
  labelledBy: string;
  options: RoleOption[];
  value: Role;
  onValueChange: (role: Role) => void;
};

/** A choice that changes what new people can do: each option says what it allows and who holds it now. */
export function RoleChoice({
  labelledBy,
  options,
  value,
  onValueChange,
}: RoleChoiceProps) {
  function changeValue(nextValue: unknown) {
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <RadioGroup
      aria-labelledby={labelledBy}
      value={value}
      onValueChange={changeValue}
      className='hairline-divide-y divide-border gap-0'
    >
      {options.map((option) => {
        const holdersLine = holdersLineOf(option.holders);

        return (
          <label
            key={option.value}
            className='has-data-checked:bg-primary/[0.06] flex cursor-pointer items-start gap-3 px-4 py-3 transition-colors duration-150 first:rounded-t-xl last:rounded-b-xl'
          >
